/**
 * 卡牌整數編碼與產線結果逐位元組一致。
 *
 * 編碼公式：card = (花色碼 + CARD_SUIT_HEX_OFFSET) × CARD_ENCODING_BASE + 點數碼
 * 花色與點數依下列公式編碼。
 */

const CARD_SUIT_HEX_OFFSET = 10;
const CARD_ENCODING_BASE = 16;

// suit code: 0=♠ 1=♥ 2=♣ 3=♦；rank code: 1=A ... 10 ... 11=J 12=Q 13=K
const encodeCard = (suitCode, rankCode) =>
  (suitCode + CARD_SUIT_HEX_OFFSET) * CARD_ENCODING_BASE + rankCode;

const decodeCardSuit = (card) =>
  Math.floor((card & 240) / CARD_ENCODING_BASE) - CARD_SUIT_HEX_OFFSET;

