const FROG_CROSS_DIFFICULTY_MAP = {
  Easy: { frogCount: 3, padCount: 4 },
  Medium: { frogCount: 2, padCount: 3 },
  Hard: { frogCount: 1, padCount: 2 },
  Expert: { frogCount: 1, padCount: 3 },
  Master: { frogCount: 1, padCount: 4 },
};

